import 'package:flutter/material.dart';
import '../../services/app_session.dart';
import '../../theme/app_theme.dart';
import '../../widgets/app_shell.dart';
import 'device_editor_screen.dart';
import 'history_screen.dart';
import 'mobile_widgets.dart';
import 'sensor_editor_screen.dart';

class DeviceDetailScreen extends StatelessWidget{final AppSession session;final Map<String,dynamic> device;const DeviceDetailScreen({super.key,required this.session,required this.device});
Map<String,dynamic> current(){for(final d in session.devices){if('${d['id']}'=='${device['id']}')return d;}return device;}
Future<void> _menu(BuildContext c,String action,Map<String,dynamic>d)async{if(action=='edit'){await Navigator.push(c,MaterialPageRoute(builder:(_)=>DeviceEditorScreen(session:session,device:d)));}else if(action=='add'){await Navigator.push(c,MaterialPageRoute(builder:(_)=>SensorEditorScreen(session:session,device:d)));}else if(action=='delete'){if(!await confirmDelete(c,'Cihaz silinsin mi?','Cihaza bağlı sensör varsa önce sensörleri silin. Bu işlem kalıcıdır.'))return;final ok=await session.deleteDevice(int.parse('${d['id']}'));if(!c.mounted)return;if(ok)Navigator.pop(c);else showSessionMessage(c,session.error??'Cihaz silinemedi.');}}
Future<void> _sensorAction(BuildContext c,String action,Map<String,dynamic>d,Map<String,dynamic>s)async{if(action=='edit'){await Navigator.push(c,MaterialPageRoute(builder:(_)=>SensorEditorScreen(session:session,device:d,sensor:s)));}else if(action=='delete'){if(!await confirmDelete(c,'Sensör silinsin mi?','Sensör ve ona ait ölçüm/alarm geçmişi kalıcı olarak silinir.'))return;final ok=await session.deleteSensor(int.parse('${s['id']}'));if(c.mounted)showSessionMessage(c,ok?'Sensör silindi.':session.error??'Sensör silinemedi.');}}
@override Widget build(BuildContext context)=>Scaffold(body:AppBackground(child:AnimatedBuilder(animation:session,builder:(context,_){final d=current(),sensors=session.sensors.where((s)=>'${s['device_id']}'=='${d['id']}').toList(),catalog=session.metricCatalog,offline=int.tryParse('${session.company['offline_minutes']??3}')??3,online=isOnline(d,offlineMinutes:offline),path=locationPath(session.locations,d['location_id']);return ListView(padding:const EdgeInsets.only(bottom:30),children:[MobileTopBar(title:d['name']?.toString()??d['code']?.toString()??'Cihaz',subtitle:path.isEmpty?'Konum atanmamış':path,actions:[if(session.canManage)PopupMenuButton<String>(onSelected:(v)=>_menu(context,v,d),itemBuilder:(_)=>const[PopupMenuItem(value:'add',child:ListTile(leading:Icon(Icons.add_chart),title:Text('Sensör ekle'))),PopupMenuItem(value:'edit',child:ListTile(leading:Icon(Icons.edit_outlined),title:Text('Cihazı düzenle'))),PopupMenuItem(value:'delete',child:ListTile(leading:Icon(Icons.delete_outline),title:Text('Cihazı sil')))]),IconButton(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.close))]),Padding(padding:const EdgeInsets.symmetric(horizontal:18),child:Column(children:[Panel(child:Column(children:[Row(children:[Container(width:54,height:54,decoration:BoxDecoration(color:AppTheme.panel2,borderRadius:BorderRadius.circular(15)),child:Icon(Icons.memory,color:online?AppTheme.green:AppTheme.cyan,size:30)),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(d['code']?.toString()??'',style:const TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:4),Text(online?'Çevrimiçi':'Çevrimdışı',style:TextStyle(color:online?AppTheme.green:const Color(0xFFFF6B6B),fontWeight:FontWeight.w800))])),Text(ago(d['last_seen']),style:const TextStyle(color:AppTheme.muted,fontSize:10))]),const SizedBox(height:14),Row(children:[Expanded(child:MetricTile(icon:Icons.battery_5_bar,label:'Batarya',value:formatValue(d['battery_percent'],'%'),color:AppTheme.green)),const SizedBox(width:8),Expanded(child:MetricTile(icon:Icons.network_wifi,label:'Sinyal',value:formatValue(d['signal_dbm'],'dBm')))])])),const SizedBox(height:16),Row(children:[Expanded(child:Text('Sensörler (${sensors.length})',style:const TextStyle(fontSize:17,fontWeight:FontWeight.w900))),if(session.canManage)TextButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>SensorEditorScreen(session:session,device:d))),icon:const Icon(Icons.add),label:const Text('Sensör'))]),const SizedBox(height:8),if(sensors.isEmpty)const Panel(child:Text('Bu cihaz için sensör kaydı bulunmuyor.',style:TextStyle(color:AppTheme.muted)))else...sensors.map((s){final m=s['metric']?.toString()??'';return Padding(padding:const EdgeInsets.only(bottom:9),child:Panel(padding:EdgeInsets.zero,child:ListTile(contentPadding:const EdgeInsets.fromLTRB(12,7,7,7),leading:CircleAvatar(backgroundColor:metricColor(m).withOpacity(.12),child:Icon(metricIcon(m),color:metricColor(m))),title:Text(s['name']?.toString()??metricLabel(m,catalog),style:const TextStyle(fontWeight:FontWeight.w900)),subtitle:Text('${s['channel']??''} • ${ago(s['latest_at'])}',style:const TextStyle(color:AppTheme.muted,fontSize:10)),trailing:Row(mainAxisSize:MainAxisSize.min,children:[Text(formatValue(s['latest_value'],metricUnit(m,catalog)),style:const TextStyle(fontWeight:FontWeight.w900,fontSize:15)),if(session.canManage)PopupMenuButton<String>(onSelected:(v)=>_sensorAction(context,v,d,s),itemBuilder:(_)=>const[PopupMenuItem(value:'edit',child:Text('Düzenle')),PopupMenuItem(value:'delete',child:Text('Sil'))])else const Icon(Icons.chevron_right)]),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>HistoryScreen(session:session,sensor:s))))));}),const SizedBox(height:8),Panel(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Cihaz Bilgileri',style:TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:10),_Info('Firmware',d['firmware_version']?.toString()??'—'),_Info('Yerel IP',d['local_ip']?.toString()??'—'),_Info('Son görülen IP',d['last_ip']?.toString()??'—'),_Info('Güç kaynağı',d['power_source']?.toString()??'—')]))]))]);}))));}
class _Info extends StatelessWidget{final String a,b;const _Info(this.a,this.b);@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.symmetric(vertical:6),child:Row(children:[Expanded(child:Text(a,style:const TextStyle(color:AppTheme.muted))),Flexible(child:Text(b,textAlign:TextAlign.right,style:const TextStyle(fontWeight:FontWeight.w700)))]));}
